-- Run once after 202610090001_document_text.sql. Replaces whole paragraphs, found by their opening words.
-- Stops and changes nothing if a paragraph cannot be found exactly once; safe to rerun once applied.
begin;

create or replace function pg_temp.swap(body text, prefix text, replacement text) returns text language plpgsql as $$
declare pattern text := '^[ \t]*' || prefix || '.*$'; hits int;
begin
 select count(*) into hits from regexp_matches(body, pattern, 'gn');
 if hits = 1 then return regexp_replace(body, pattern, replacement, 'n'); end if;
 if hits = 0 and position(replacement in body) > 0 then return body; end if;
 raise exception 'Living Chronicle: paragraph starting "%" found % times; nothing was changed', prefix, hits;
end; $$;

do $migration$
declare doc_id text; doc_text text; found int;
begin
 select count(*), min(id) into found, doc_id from public.library
  where id = 'DOC-2F08DD45-B36';
 if found <> 1 then raise exception 'Living Chronicle: expected one matching document, found %', found; end if;
 select l.body into doc_text from public.library l where id = doc_id;

